'use client';

import Link from 'next/link';
import { useId, useLayoutEffect, useRef, useState } from 'react';

// Port of the previous app's SlimCardShellA / SlimCardShellB (Figma exports): same geometry and copy,
// colours from design tokens, the CTA pill is a real link.

const PILL_RIGHT = 841;
const LABEL_INSET = 18;
const PILL_CHROME = 53;
const PILL_DEFAULT_W = 150;

export interface SlimCardProps {
  lead: string;
  hand: string;
  ctaLabel: string;
  href: string;
  className?: string;
}

/** The pill grows to the left with its label (measured once fonts are ready), as in the previous app. */
function usePill(ctaLabel: string) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '');
  const labelRef = useRef<SVGTextElement | null>(null);
  const [pillWidth, setPillWidth] = useState(PILL_DEFAULT_W);
  useLayoutEffect(() => {
    let cancelled = false;
    const measure = () => {
      const node = labelRef.current;
      if (!node || cancelled || typeof node.getBBox !== 'function') return;
      try {
        const width = node.getBBox().width;
        if (width > 0) setPillWidth(Math.round(width) + PILL_CHROME);
      } catch {
        // getBBox throws while the SVG isn't rendered (display: none); keep the default width.
      }
    };
    measure();
    document.fonts?.ready?.then(measure).catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [ctaLabel]);
  return { uid, labelRef, pillWidth };
}

/** Slim card A: lead + handwritten line on the left, CTA pill on the right (tasks / catch-up states). */
